// ==========================================
// Adapter: flattens LEGO_DATABASE (theme -> crate -> figure) into the
// MINIFIG_DATABASE array and CRATES array that app.js consumes.
// Keeps the authoring format (grouped by theme/crate) decoupled from the
// runtime format the UI expects, without requiring changes anywhere else.
// ==========================================
const MINIFIG_DATABASE = [];
const CRATES = [];

Object.values(LEGO_DATABASE).forEach(theme => {
    (theme.crates || []).forEach(crate => {
        const pool = [];
        (crate.minifigs || []).forEach(fig => {
            if (!MINIFIG_DATABASE.some(f => f.id === fig.id)) {
                MINIFIG_DATABASE.push({ ...fig, theme: theme.themeName });
            }
            pool.push(fig.id);
        });

        CRATES.push({
            id: crate.id,
            name: crate.name,
            cost: crate.cost,
            image: crate.image,
            weights: crate.weights,
            theme: theme.themeName,
            pool
        });
    });
});